<?php
namespace App\Http\Controllers\Public;
use App\Http\Controllers\Controller; use App\Http\Controllers\Public\Concerns\HandlesCatalogInteractions; use App\Models\CatalogEntity; use App\Models\FeatureFlag; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\View\View;
class EventController extends Controller
{use HandlesCatalogInteractions;private function enabled():void{abort_unless(FeatureFlag::where('key_name','public-event')->where('status','enabled')->exists(),404);}public function index(Request $r):View{$this->enabled();$items=CatalogEntity::publicDomain('event')->whereHas('event',fn($q)=>$q->where('ends_at','>=',now()))->with(['event.ticketTypes.offer','media','location'])->when($r->q,fn($q,$v)=>$q->where('name','like','%'.$v.'%'))->when($r->from,fn($q,$v)=>$q->whereHas('event',fn($x)=>$x->whereDate('starts_at','>=',$v)))->paginate(12)->withQueryString();return view('public.catalog-domain.index',['items'=>$items,'title'=>'Event','routePrefix'=>'event']);}public function show(string $slug):View{$this->enabled();$item=CatalogEntity::publicDomain('event')->where('slug',$slug)->with(['event.schedules','event.ticketTypes.offer','media','facilities','reviews'=>fn($q)=>$q->where('status','published')->with('reply')])->firstOrFail();return view('public.catalog-domain.show',['item'=>$item,'title'=>'Event','routePrefix'=>'event']);}public function favorite(Request $r,string $slug):RedirectResponse{return $this->toggleFavorite($r,CatalogEntity::publicDomain('event')->where('slug',$slug)->firstOrFail(),true);}public function unfavorite(Request $r,string $slug):RedirectResponse{return $this->toggleFavorite($r,CatalogEntity::publicDomain('event')->where('slug',$slug)->firstOrFail(),false);}public function review(Request $r,string $slug):RedirectResponse{return $this->storeReview($r,CatalogEntity::publicDomain('event')->where('slug',$slug)->firstOrFail());}}
